// The gateway's one page for every role (docs/50), on the plain server and the database
// e2e/console_server.py seeded for this run. Each account logs in at /dashboard/, sees exactly the
// navigation its role gives (the table of docs/console-integration-plan.md, section 2.3: kept
// here, in the tests, never in the page), opens each item shown, and is refused one hidden item
// by its address. Then: a deep link from logged out, a session ended from elsewhere, the
// console's old address, and a leak scan of all of it with its planted control. The passwords
// were generated by playwright.config.ts at the start of the run.

import {
  expect,
  test,
  type Browser,
  type Locator,
  type Page,
  type TestInfo,
} from "@playwright/test";

test.describe.configure({ mode: "serial" });

const NOT_AVAILABLE = "That page is not available to this account.";
const SESSION_ENDED = "Your session has ended. Log in again.";

function secret(name: string): string {
  const value = process.env[name];
  if (value === undefined || value === "") {
    throw new Error(`${name} is not set: run the tests through playwright.config.ts`);
  }
  return value;
}

interface Account {
  username: string;
  first: string;
  second: string;
}

function account(username: string, first: string, second: string): Account {
  return { username, first, second };
}

const OPERATOR = account(
  "operator-e2e",
  "CONSOLE_E2E_OPERATOR_PASSWORD",
  "CONSOLE_E2E_OPERATOR_NEW_PASSWORD",
);
const ADMIN = account(
  "admin-e2e",
  "CONSOLE_E2E_ADMIN_FIRST_PASSWORD",
  "CONSOLE_E2E_ADMIN_PASSWORD",
);
const ORG_READER = account(
  "viewer-e2e",
  "CONSOLE_E2E_VIEWER_FIRST_PASSWORD",
  "CONSOLE_E2E_VIEWER_PASSWORD",
);
const APP_ADMIN = account(
  "appadmin-e2e",
  "CONSOLE_E2E_APPADMIN_FIRST_PASSWORD",
  "CONSOLE_E2E_APPADMIN_PASSWORD",
);
const APP_READER = account(
  "appviewer-e2e",
  "CONSOLE_E2E_APPVIEWER_FIRST_PASSWORD",
  "CONSOLE_E2E_APPVIEWER_PASSWORD",
);
const NO_ROLE = account(
  "norole-e2e",
  "CONSOLE_E2E_NOROLE_FIRST_PASSWORD",
  "CONSOLE_E2E_NOROLE_PASSWORD",
);
const ALL = [OPERATOR, ADMIN, ORG_READER, APP_ADMIN, APP_READER, NO_ROLE];

/** Every password and key this run made: none may appear anywhere the scan looks. */
const SECRETS = [
  "CONSOLE_E2E_PEPPER",
  "CONSOLE_E2E_VAULT_KEY",
  ...ALL.flatMap((who) => [who.first, who.second]),
];

// --- the leak scan ----------------------------------------------------------------------------

/**
 * What a run leaves behind, gathered as it goes: every address the page was at, every request,
 * every console line, every session cookie and CSRF token the gateway gave out. At the end, what
 * the browser keeps, and what the server printed, logged and audited.
 */
class Scan {
  readonly urls: string[] = [];
  readonly requests: string[] = [];
  readonly consoleLines: string[] = [];
  readonly tokens = new Map<string, string>();

  watch(page: Page): void {
    page.on("framenavigated", (frame) => {
      if (frame === page.mainFrame()) this.urls.push(frame.url());
    });
    page.on("request", (request) => this.requests.push(request.url()));
    page.on("console", (message) => this.consoleLines.push(message.text()));
    page.on("response", (response) => {
      if (!/\/v1\/auth\/(login|me)$/.test(response.url())) return;
      void response
        .json()
        .then((body: { csrf_token?: string }) => {
          if (body.csrf_token !== undefined) {
            this.tokens.set(`csrf token ${this.tokens.size}`, body.csrf_token);
          }
        })
        .catch(() => undefined);
    });
  }

  /** The address now, as well as each navigation: a hash change is an address too. */
  async step(page: Page): Promise<void> {
    this.urls.push(page.url());
    for (const cookie of await page.context().cookies()) {
      if (cookie.name === "gw_session" && cookie.value !== "") {
        this.tokens.set(`session cookie ${cookie.value.slice(0, 4)}`, cookie.value);
      }
    }
  }

  /** Each place looked, and each secret found there. */
  async leaks(page: Page): Promise<[string, string][]> {
    await this.step(page);
    const kept = await page.evaluate(async () => {
      const dump = (storage: Storage) =>
        Array.from({ length: storage.length }, (_, i) => {
          const key = storage.key(i) ?? "";
          return `${key}=${storage.getItem(key) ?? ""}`;
        }).join(" ");
      const databases = (await indexedDB.databases()).map((d) => d.name ?? "").join(" ");
      return {
        local: dump(localStorage),
        session: dump(sessionStorage),
        databases,
        cookie: document.cookie,
      };
    });
    const mail = `http://127.0.0.1:${secret("CONSOLE_E2E_MAIL_PORT")}`;
    const output = ((await (await page.request.get(`${mail}/output`)).json()) as { output: string })
      .output;
    const audit = ((await (await page.request.get(`${mail}/audit`)).json()) as { rows: string[] })
      .rows;
    const places: Record<string, string> = {
      urls: this.urls.join(" "),
      requests: this.requests.join(" "),
      console: this.consoleLines.join(" "),
      "local storage": kept.local,
      "session storage": kept.session,
      indexeddb: kept.databases,
      "document.cookie": kept.cookie,
      "server output": output,
      "audit rows": audit.join(" "),
    };
    const secrets: [string, string][] = [
      ...SECRETS.map((name): [string, string] => [name, secret(name)]),
      ...this.tokens.entries(),
    ];
    const found: [string, string][] = [];
    for (const [where, text] of Object.entries(places)) {
      for (const [name, value] of secrets) if (text.includes(value)) found.push([where, name]);
    }
    // HttpOnly: the session cookie is the browser's, never the page's.
    expect(kept.cookie).not.toContain("gw_session");
    return found;
  }
}

// --- steps --------------------------------------------------------------------------------------

function sections(page: Page): Locator {
  return page.getByRole("navigation", { name: "Sections" });
}

/** The planted secrets visible on the page: its text and every field's value. */
async function visibleSecrets(page: Page): Promise<string[]> {
  const shown = await page.evaluate(
    () =>
      document.body.innerText +
      Array.from(document.querySelectorAll("input"), (input) => input.value).join(" "),
  );
  return SECRETS.filter((name) => shown.includes(secret(name)));
}

/** A screenshot for the PR (git-ignored run output), taken only with no secret on the page. */
async function picture(page: Page, testInfo: TestInfo, name: string): Promise<void> {
  expect(await visibleSecrets(page)).toEqual([]);
  await page.screenshot({ path: testInfo.outputPath(`${name}.png`), fullPage: true });
}

/**
 * Logs in at the page's front door. An account still on its first password (the bootstrap
 * admin's works once) is asked for a new one first, and nothing else is drawn meanwhile.
 */
async function logIn(page: Page, who: Account, scan?: Scan, testInfo?: TestInfo): Promise<void> {
  const form = page.getByRole("region", { name: "Log in" });
  await form.getByLabel("Username").fill(who.username);
  await form.getByLabel("Password").fill(secret(who.second));
  await form.getByRole("button", { name: "Log in" }).click();
  const change = page.getByRole("region", { name: "Change your password" });
  await expect(sections(page).or(change).or(form.getByRole("alert"))).toBeVisible();
  if (await sections(page).isVisible()) {
    await scan?.step(page);
    return;
  }
  if (!(await change.isVisible())) {
    await form.getByLabel("Password").fill(secret(who.first));
    await form.getByRole("button", { name: "Log in" }).click();
  }
  await expect(change).toBeVisible();
  // Only the change: no navigation, no screen.
  await expect(sections(page)).toHaveCount(0);
  if (testInfo !== undefined && who === OPERATOR) {
    await picture(page, testInfo, "forced-password-change");
  }
  await change.getByLabel("Current password").fill(secret(who.first));
  await change.getByLabel("New password").fill(secret(who.second));
  await change.getByRole("button", { name: "Change password" }).click();
  await expect(sections(page)).toBeVisible();
  await scan?.step(page);
}

interface Expected {
  account: Account;
  /** The picture's name: the role, as the plan's table names it. */
  name: string;
  navigation: string[];
  home: (string | RegExp)[];
  hidden: string;
}

const ROLES: Expected[] = [
  {
    account: OPERATOR,
    name: "platform-admin",
    navigation: ["Home", "Monitoring"],
    home: ["Platform", /^Organization /],
    hidden: "#/channels",
  },
  {
    account: ADMIN,
    name: "org-admin",
    navigation: [
      "Home",
      "Organization settings",
      "Application settings",
      "Alert rules",
      "Channels",
      "Incidents",
    ],
    home: ["Organization acme"],
    hidden: "#/monitor/overview",
  },
  {
    account: ORG_READER,
    name: "organization-reader",
    navigation: [
      "Home",
      "Organization settings",
      "Application settings",
      "Alert rules",
      "Incidents",
    ],
    home: ["Organization acme"],
    hidden: "#/channels",
  },
  {
    account: APP_ADMIN,
    name: "app-admin",
    navigation: ["Home", "Application settings", "Alert rules", "Incidents"],
    home: ["Your applications"],
    hidden: "#/organization",
  },
  {
    account: APP_READER,
    name: "application-reader",
    navigation: ["Home", "Application settings", "Alert rules", "Incidents"],
    home: ["Your applications"],
    hidden: "#/channels",
  },
  {
    account: NO_ROLE,
    name: "no-role",
    navigation: ["Home"],
    home: ["No access yet"],
    hidden: "#/organization",
  },
];

// --- every role -----------------------------------------------------------------------------------

for (const role of ROLES) {
  test(`${role.name}: exactly its navigation, its home, each item, one refused by address, no leak`, async ({
    page,
  }, testInfo) => {
    const scan = new Scan();
    scan.watch(page);
    await page.goto("/dashboard/");
    await logIn(page, role.account, scan, testInfo);

    await expect(sections(page).getByRole("link")).toHaveText(role.navigation);
    const home = page.getByRole("region", { name: "Home" });
    for (const region of role.home) {
      await expect(home.getByRole("region", { name: region })).toBeVisible();
    }
    await picture(page, testInfo, `home-${role.name}`);

    // Each item shown opens its screen.
    for (const label of role.navigation.slice(1)) {
      await sections(page).getByRole("link", { name: label, exact: true }).click();
      await expect(page.getByRole("heading", { name: label, level: 2 })).toBeVisible();
      await scan.step(page);
    }

    // One it does not show, opened by its address: home, with one sentence.
    await page.goto(`/dashboard/${role.hidden}`);
    await expect(page.getByRole("region", { name: "Home" }).getByRole("alert")).toHaveText(
      NOT_AVAILABLE,
    );
    await scan.step(page);
    await picture(page, testInfo, `hidden-${role.name}`);

    expect(await scan.leaks(page)).toEqual([]);
  });
}

// --- deep links, ended sessions, the old address ----------------------------------------------

async function freshPage(browser: Browser, testInfo: TestInfo): Promise<Page> {
  const context = await browser.newContext({
    baseURL: testInfo.project.use.baseURL,
    viewport: { width: 1400, height: 1000 },
  });
  return context.newPage();
}

test("a deep link from logged out returns to its place after login", async ({
  browser,
}, testInfo) => {
  const page = await freshPage(browser, testInfo);
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/rules/app-one");
  await expect(page.getByRole("region", { name: "Log in" })).toBeVisible();
  await picture(page, testInfo, "login");
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Alert rules", level: 2 })).toBeVisible();
  await expect(page.getByRole("combobox", { name: "Application", exact: true })).toHaveValue(
    "app-one",
  );
  expect(new URL(page.url()).hash).toBe("#/rules/app-one");
  expect(await scan.leaks(page)).toEqual([]);
  await page.context().close();
});

test("a session ended elsewhere sends the page to login, and back to its place", async ({
  browser,
}, testInfo) => {
  const page = await freshPage(browser, testInfo);
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/incidents");
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Incidents", level: 2 })).toBeVisible();

  // Another browser holding the same session logs it out: the gateway forgets it.
  const session = (await page.context().cookies()).find((c) => c.name === "gw_session");
  expect(session).toBeDefined();
  const other = await browser.newContext({ baseURL: testInfo.project.use.baseURL });
  if (session !== undefined) await other.addCookies([session]);
  const me = (await (await other.request.get("/v1/auth/me")).json()) as { csrf_token: string };
  const out = await other.request.post("/v1/auth/logout", {
    headers: { "X-CSRF-Token": me.csrf_token },
    data: {},
  });
  expect(out.status()).toBe(200);
  await other.close();

  // The next section the page opens learns it: login, where it was, with the reason.
  await sections(page).getByRole("link", { name: "Channels", exact: true }).click();
  const login = page.getByRole("region", { name: "Log in" });
  await expect(login).toContainText(SESSION_ENDED);
  expect(new URL(page.url()).hash).toBe("#/channels");
  await picture(page, testInfo, "session-ended");
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Channels", level: 2 })).toBeVisible();
  expect(await scan.leaks(page)).toEqual([]);
  await page.context().close();
});

test("the console's old address opens the same place on the one page", async ({ page }) => {
  await page.goto("/dashboard/console.html#/channels");
  await expect(page).toHaveURL(/\/dashboard\/#\/channels$/);
  await expect(page.getByRole("region", { name: "Log in" })).toBeVisible();
});

test("logging out leaves the next person at home", async ({ page }) => {
  await page.goto("/dashboard/#/organization");
  await logIn(page, ORG_READER);
  await expect(
    page.getByRole("heading", { name: "Organization settings", level: 2 }),
  ).toBeVisible();
  await page.getByRole("button", { name: "Log out" }).click();
  await expect(page.getByRole("region", { name: "Log in" })).toContainText("Logged out.");
  expect(new URL(page.url()).hash).toBe("#/home");
});

test("leak scan control: a password planted in storage and in the address is found", async ({
  page,
}) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ORG_READER, scan);
  expect(await scan.leaks(page)).toEqual([]);

  // Planted by this test, not the page: a value made from the password, in session storage and
  // in the URL's fragment. The scan must find both, or it could not be trusted to find a leak.
  const marker = `planted-${secret(ORG_READER.second)}`;
  await page.evaluate((value) => {
    sessionStorage.setItem("planted", value);
    window.location.hash = `#/${encodeURIComponent(value)}`;
  }, marker);
  await expect(page.getByRole("region", { name: "Home" }).getByRole("alert")).toHaveText(
    NOT_AVAILABLE,
  );
  const found = await scan.leaks(page);
  expect(found).toContainEqual(["session storage", ORG_READER.second]);
  expect(found).toContainEqual(["urls", ORG_READER.second]);
  await page.evaluate(() => {
    sessionStorage.removeItem("planted");
  });
});
